// config/validate-secrets.js
export const validateSecrets = () => {
  const warnings = [];
  const errors = [];

  // Check JWT_SECRET strength
  if (process.env.JWT_SECRET) {
    const strength = calculateSecretStrength(process.env.JWT_SECRET);
    if (strength < 80) {
      warnings.push('JWT_SECRET strength is weak. Use at least 32 random characters.');
    }
  }

  // Check for placeholder values that might have been accidentally committed
  const placeholderPatterns = [
    { pattern: /your-.*-here/i, message: 'Replace placeholder values' },
    { pattern: /CHANGE_ME/i, message: 'Change placeholder value' },
    { pattern: /example/i, message: 'Replace example values' }
  ];

  for (const [key, value] of Object.entries(process.env)) {
    for (const { pattern, message } of placeholderPatterns) {
      if (pattern.test(value)) {
        if (key.includes('SECRET') || key.includes('PASSWORD') || key.includes('KEY')) {
          errors.push(`${key}: ${message}`);
        }
      }
    }
  }

  return { errors, warnings };
};

const calculateSecretStrength = (secret) => {
  let score = 0;
  if (!secret) return 0;

  if (secret.length >= 16) score += 20;
  if (secret.length >= 32) score += 20;
  if (/[a-z]/.test(secret)) score += 10;
  if (/[A-Z]/.test(secret)) score += 10;
  if (/[0-9]/.test(secret)) score += 10;
  if (/[^a-zA-Z0-9]/.test(secret)) score += 30;

  return Math.min(score, 100);
};
