- Secrets in error messages can be exposed to users
- Secret values might leak in exception stack traces
- No sanitization of secret values before they reach logging systems

**Secure Implementation**:
```javascript
// Add secret-sanitizer.js
export function sanitizeForLogging(obj) {
  const sensitiveKeys = [
    'password', 'secret', 'token', 'api_key', 'apikey', 'access_key', 
    'secret_key', 'credential', 'auth', 'bearer', 'authorization'
  ];

  function sanitize(value) {
    if (typeof value === 'string') {
      if (value.length > 10) {
        return value.slice(0, 4) + '***' + value.slice(-4);
      }
      return '***';
    }
    return value;
  }

  if (Array.isArray(obj)) {
    return obj.map(item => sanitizeForLogging(item));
  }

  if (typeof obj === 'object' && obj !== null) {
    const sanitized = {};
    for (const [key, value] of Object.entries(obj)) {
      const lowerKey = key.toLowerCase();
      if (sensitiveKeys.some(sk => lowerKey.includes(sk))) {
        sanitized[key] = sanitize(value);
      } else {
        sanitized[key] = sanitizeForLogging(value);
      }
    }
    return sanitized;
  }

  return obj;
}

// Usage in app.js error handler
const errorHandler = (err, req, res, next) => {
  // Log sanitized error details
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV !== 'production' ? sanitizeForLogging(err.stack) : undefined,
    type: err.constructor.name,
  });

  // Send generic error message to client
  res.status(err.status || 500).json({
    error: err.status === 429 ? err.message : 'Internal server error',
  });
};
