// Add secret-scoper.js
export class SecretScoper {
  constructor() {
    this.allowedSecrets = new Set([
      'DATABASE_URL',
      'API_KEY',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY'
    ]);
  }

  getScopedEnv() {
    const scoped = {};
    for (const [key, value] of Object.entries(process.env)) {
      if (this.allowedSecrets.has(key)) {
        scoped[key] = '***'; // Only expose masked values
      }
    }
    return scoped;
  }
}

