        `  ✓ Embedding model OK (${this.config.embeddingModel}, ` +
        `dim=${vecs[0].length}, ${Date.now() - embedStart}ms)`
      );
    } catch (err) {
      throw new Error(
        `Embedding model ${this.config.embeddingModel} failed: ${err instanceof Error ? err.message : String(err)}`
      );
    }

