// Secure error handling middleware
const secureErrorHandler = (err, req, res, next) => {
  // Log sanitized error details
  const logData = {
    timestamp: new Date().toISOString(),
    requestId: req.id || null,
    method: req.method,
    path: req.path,
    ip: req.ip || req.connection.remoteAddress,
    userAgent: req.headers['user-agent'] || '',
    error: {
      message: err.message || 'Unknown error',
      type: err.constructor.name,
      code: err.code || null,
    },
    stack: process.env.NODE_ENV !== 'production' ? err.stack : 'Sensitive information hidden',
  };

  // Don't include the full stack in production logs
  if (process.env.NODE_ENV === 'production') {
    logData.stack = null;
  }

  console.error('Application error:', JSON.stringify(logData, null, 2));

  // Send generic error response
  const statusCode = err.status || err.statusCode || 500;
  const isRateLimit = statusCode === 429;

  const response = {
    error: isRateLimit ? err.message : 'Internal server error',
    code: err.code || 'INTERNAL_ERROR',
    timestamp: new Date().toISOString(),
    requestId: req.id || null,
  };

  // Only include additional info in development
  if (process.env.NODE_ENV !== 'production') {
    response.reason = err.message;
    if (err.validationErrors) {
      response.validationErrors = err.validationErrors;
    }
  }

  // Ensure we don't leak sensitive information
  delete response.reason; // In production, this would be hidden

  res.status(statusCode).json(response);
};
```

