const errorHandler = (err, req, res, next) => {
  // Log detailed error for developers
  console.error('Error occurred:', {
    message: err.message,
    stack: process.env.NODE_ENV !== 'production' ? err.stack : undefined,
    type: err.constructor.name,
    timestamp: new Date().toISOString(),
    url: req.originalUrl,
    method: req.method,
    ip: req.ip,
  });

  // Determine if stack trace should be sent (never in production)
  const sendStackTrace = process.env.NODE_ENV === 'development' && 
                         process.env.SHOW_DEBUG_STACK === 'true';

  // Send generic error message to client
  res.status(err.status || 500).json({
    error: err.status === 429 ? err.message : 'Internal server error',
    ...(sendStackTrace ? { stack: err.stack } : {}),
    ...(process.env.NODE_ENV === 'development' ? { errorCode: err.code } : {}),
  });
};
```

