                         process.env.SHOW_DEBUG_STACK === 'true';

  // Send generic error message to client
  res.status(err.status || 500).json({
    error: err.status === 429 ? err.message : 'Internal server error',
    ...(sendStackTrace ? { stack: err.stack } : {}),
    ...(process.env.NODE_ENV === 'development' ? { errorCode: err.code } : {}),
  });
};
```

---

### 8. Missing Security Logging and Monitoring

**Severity: HIGH**

**Issue:** The application lacks comprehensive security logging.

**Risk:** Inability to detect and respond to security incidents

**Recommendation:**
```javascript
const morgan = require('morgan');
const winston = require('winston');

// Security-focused request logging
app.use(morgan('combined', {
  stream: {
    write: (message) => {
      // Log all requests for security analysis
      winston.info(`Request: ${message.trim()}`);
    }
  }
}));

// Create security logger
const securityLogger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ 
      filename: 'logs/security.log', 
      level: 'warning',
      maxsize: 5242880, // 5MB
      maxFiles: 5,
    }),
    new winston.transports.Console()
  ]
});

// Log suspicious activities
const logSuspiciousActivity = (req, reason) => {
  securityLogger.warning({
    type: 'suspicious_activity',
    timestamp: new Date().toISOString(),
    ip: req.ip,
    url: req.originalUrl,
    method: req.method,
    reason: reason,
    userAgent: req.headers['user-agent']
  });
};
```

---

### 9. Missing HTTP-only and Secure Cookie Settings

**Severity: HIGH**

**Issue:** Session management and cookie settings are not explicitly configured.

**Risk:** Session hijacking, cookie theft

**Recommendation:**
```javascript
const session = require('express-session');

// Secure session configuration
app.use(session({
  secret: process.env.SESSION_SECRET,
  name: 'sid', // Custom session cookie name
  resave: false,
  saveUninitialized: false,
  cookie: {
    secure: process.env.NODE_ENV === 'production',
    httpOnly: true,
    sameSite: 'strict', // or 'lax'
    maxAge: 24 * 60 * 60 * 1000, // 24 hours
    domain: '.yourdomain.com',
    path: '/',
  },
  rolling: true,
  store: new RedisStore({ client: redisClient }), // Use Redis for session storage
}));
```

---

### 10. Missing Security Headers for Specific Endpoints

**Severity: LOW**

**Issue:** Some headers might need to be set differently for specific routes.

**Risk:** Suboptimal security posture

**Recommendation:**
```javascript
// Set different cache control for sensitive data
app.use('/api/users', (req, res, next) => {
  res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
  next();
});

// Set permissions policy
app.use((req, res, next) => {
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');
  next();
});
```

---

## Additional Security Recommendations

### 1. Dependency Security
```bash
# Regularly update dependencies
npm audit fix
npm audit

# Use npm audit or similar tools
snyk test
```

### 2. XSS Protection
```javascript
// Add XSS protection middleware
const xss = require('xss');

const sanitizeObject = (obj) => {
  if (typeof obj !== 'object' || obj === null) {
    return obj;
  }

  const sanitized = {};
  for (const key in obj) {
    if (typeof obj[key] === 'string') {
      sanitized[key] = xss(obj[key]);
    } else if (typeof obj[key] === 'object' && obj[key] !== null) {
      sanitized[key] = sanitizeObject(obj[key]);
    } else {
      sanitized[key] = obj[key];
    }
  }
  return sanitized;
};

// Apply sanitization to request body (use carefully for JSON APIs)
```

### 3. Secure File Handling
```javascript
// If file uploads are needed
const path = require('path');

const sanitizeFileName = (filename) => {
  return path.basename(filename).replace(/[^a-zA-Z0-9._-]/g, '');
};

const validateFileType = (mimetype) => {
  const allowedTypes = ['image/jpeg', 'image/png', 'application/pdf'];
  return allowedTypes.includes(mimetype);
};
```

### 4. JSON Serialization Safety
```javascript
// Prevent prototype pollution
app.use(express.json({
  limit: '10kb',
  strict: true,
  reviver: (key, value) => {
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
      return undefined;
    }
    return value;
  }
}));
```

---

## Summary Checklist

