  console.log(`${signal} signal received: closing HTTP server`);
  server.close(() => {
    console.log('HTTP server closed');
    // Close database connections if applicable
    process.exit(0);
  });

  // Force close after 10 seconds if connections don't close
  setTimeout(() => {
