  if (params.defences)   env.TEST25_DEFENCES     = String(params.defences);
  if (params.scenarios)  env.TEST25_SCENARIOS    = String(params.scenarios);
  if (params.attackTypes) env.TEST25_ATTACK_TYPES = String(params.attackTypes);
  if (params.seed)       env.TEST25_SEED         = String(params.seed);
  if (params.maxTurns)   env.TEST25_MAX_TURNS    = String(params.maxTurns);
  if (params.backend)    env.TEST25_BACKEND      = String(params.backend);
  if (params.runId)      env.TEST25_RUN_ID       = String(params.runId);

  // Mode 4 env vars (Paper14 §VII behavioural drift). Most callers will
  // pass these through `params.env`; these convenience mappings mirror the
  // entrypoint's env contract for the common knobs.
  if (params.models)     env.AGENT_MODELS = String(params.models);
  if (params.configs)    env.CONFIGS      = String(params.configs);
  if (params.floodTurns) env.FLOOD_TURNS  = String(params.floodTurns);
  if (params.reps)       env.REPETITIONS  = String(params.reps);
  if (params.rcThreshold) env.RC_THRESHOLD = String(params.rcThreshold);
  if (params.concurrency) env.RUNNER_CONCURRENCY = String(params.concurrency);
  if (params.runId)      env.RUN_ID       = String(params.runId);

  // Generic env passthrough (test 12 / AgentDojo uses this)
  if (params.env && typeof params.env === "object") {
    for (const [k, v] of Object.entries(params.env)) {
      env[k] = String(v);
    }
  }

  // Shared env vars
  if (params.s3Bucket)  env.S3_BUCKET       = String(params.s3Bucket);
  if (params.s3Prefix)  env.S3_PREFIX       = String(params.s3Prefix);
  if (params.s3Region)  env.S3_REGION       = String(params.s3Region);
  if (params.awsRegion) env.AWS_REGION      = String(params.awsRegion);
  if (params.bedrockRegion) env.BEDROCK_REGION = String(params.bedrockRegion);

  const runId = env.TEST7_RUN_ID || env.TEST3_RUN_ID || new Date().toISOString().replace(/[:.]/g, "");

  state = {
    status: "running",
    runId,
    params,
    startedAt: new Date().toISOString(),
    finishedAt: null,
    exitCode: null,
    pid: null,
    logLines: [],
    progress: { ...INITIAL_PROGRESS },
  };

  const child = spawn(entrypoint, [], {
    env,
    stdio: ["ignore", "pipe", "pipe"],
  });

  state.pid = child.pid;
  currentProcess = child;

  child

// Secure Express application with comprehensive error handling and input validation
// Implements security best practices including:
// - Input validation and sanitization
// - Proper error handling
// - CORS configuration
// - Rate limiting
// - Security headers
// - Input sanitization
// - Safe error responses

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// Enable security headers (helmet)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      frameAncestors: ["'none'"],
    },
  },
  crossOriginEmbedderPolicy: true,
  crossOriginOpenerPolicy: true,
  crossOriginResourcePolicy: { policy: "same-site" },
  dnsPrefetchControl: { allow: false },
  frameguard: { action: "deny" },
  hidePoweredBy: true,
  httpStrictTransportSecurity: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  ieNoOpen: true,
  noSniff: true,
  originAgentCluster: true,
  permittedCrossDomainPolicies: { permittedPolicies: "none" },
  referrerPolicy: { policy: "strict-origin-when-cross-origin" },
  xssFilter: true,
}));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { 
    error: 'Too many requests from this IP, please try again in 15 minutes' 
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all requests
app.use(limiter);

// Parse JSON bodies with size limit and safe parsing
app.use(express.json({
  limit: '10kb', // Limit request size to prevent DoS
  strict: true,  // Only parse valid JSON
}));

// Parse URL-encoded bodies with size limit
app.use(express.urlencoded({
  extended: true,
  limit: '10kb',
  parameterLimit: 1000,
}));

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Validate input for user-related operations
