};

// Apply to user endpoints
app.get('/users', authenticateToken, validateUserOwnership, validateUserIdQuery, handleValidationErrors, ...);
app.put('/users/:id', authenticateToken, validateUserOwnership, validateId, validateUserUpdate, handleValidationErrors, ...);
```

## Additional Recommendations

### For Production Deployment:

1. **Enable HTTPS only**
```javascript
if (process.env.NODE_ENV === 'production') {
  app.enable('trust proxy'); // For proper IP detection behind proxy
  app.use((req, res, next) => {
    if (req.protocol !== 'https') {
      return res.redirect(301, 'https://' + req.headers.host + req.url);
    }
    next();
  });
}
```

2. **Add CSRF Protection**
```javascript
const csurf = require('csurf');
app.use(csurf());
// Include _csrf token in forms and validate
```

3. **Session Security**
