```

**Recommendation:** Implement a proper secrets management solution:

```javascript
// Secure secrets management using AWS Secrets Manager
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretManager {
  constructor() {
    this.cache = {};
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
    });
    this.secretPrefix = process.env.SECRET_PREFIX || 'app/';
  }

  async getSecret(secretName) {
    // Cache secrets to avoid repeated API calls
    if (this.cache[secretName]) {
      return this.cache[secretName];
    }

    try {
      const response = await this.client.send(
        new GetSecretValueCommand({
          SecretId: `${this.secretPrefix}${secretName}`,
          VersionStage: 'AWSCURRENT',
        })
      );

      const secret = JSON.parse(response.SecretString);
      this.cache[secretName] = secret;
      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error.message);
      throw error;
    }
  }

  async getDatabaseUrl() {
    const secrets = await this.getSecret('database');
    return secrets.DB_URL;
  }

  async getApiKey(provider) {
    const secrets = await this.getSecret(`${provider}-api`);
    return secrets.API_KEY;
  }
}

// Usage example
const secretManager = new SecretManager();

// Configure the app with secrets
app.use((req, res, next) => {
  // Load secrets lazily
  if (!process.env.DATABASE_URL) {
    process.env.DATABASE_URL = await secretManager.getDatabaseUrl();
  }
  next();
});
```

