```javascript
// Detect potential secret leaks
const CANARY_PATTERNS = [
  /CANARY|test|example|placeholder/i,
  /AKIA[0-9A-Z]{16}/, // AWS access key pattern
  /sk_live_[a-zA-Z0-9]{24,}/, // Stripe pattern
];

