/**
 * Credential Validation Utility
 * 
 * Usage: This module provides validation functions for credentials before rotation.
 * Run with: node credential-validators.mjs
 * 
 * This script validates:
 * - Format compliance (length, character set, prefixes)
 * - Sensitivity detection (prevents logging real secrets)
 * - AWS credential chain configuration
 * - Clerk API key validation
 */

/**
 *敏感环境变量检测 - Stand-alone module so both InMemorySessionStore
 * and DynamoSessionStore can call it without creating a circular import
 * with server-core.ts (which imports the stores).
 *
 * Two heuristics, OR-combined:
 *
 *  1. NAME suggests credential. Extended over the original
 *     KEY|SECRET|TOKEN|PASSWORD|CREDENTIAL|API regex to catch URL-style
 *     vars (DATABASE_URL, MONGO_URI, REDIS_URL, SMTP_URL, WEBHOOK_URL,
 *     CONNECTION_STRING, DSN…) that frequently embed user:password@host.
 *     Plus AUTH/PRIVATE/PASSWD/SMTP/WEBHOOK families.
 *
 *  2. VALUE looks like a credential regardless of name. Catches secrets
 *     that landed in unconventionally-named vars.
 *
 * False-positive cost is "we redact a non-secret value", which is annoying
 * for debugging but not a security regression. Worth it.
 */
export function isSensitiveEnvVar(name, value) {
  // 1. Name-based check.
  if (/KEY|SECRET|TOKEN|PASSWORD|PASSWD|CREDENTIAL|API|AUTH|PRIVATE|DSN|URL|URI|CONNECTION|DATABASE|SMTP|WEBHOOK/i.test(name)) {
    return true;
  }
  // 2. Value-shape checks (only on strings of meaningful length).
  if (typeof value !== "string" || value.length < 8) return false;
  // URL with embedded user:password@host
  if (/^[a-z][a-z0-9+\-.]*:\/\/[^/\s]+:[^@\s]+@/i.test(value)) return true;
  // JWT shape (header.payload.signature where each segment is base64url)
  if (/^eyJ[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{10,}/.test(value)) return true;
  // AWS access key family (AKIA, ASIA, etc. + 16 alnum chars)
  if (/^A(?:KIA|SIA|GPA|IDA|ROA|IPA|NPA|NVA)[0-9A-Z]{16}$/.test(value)) return true;
  // GitHub PAT (ghp_, gho_, ghu_, ghs_, ghr_)
  if (/^gh[pousr]_[A-Za-z0-9]{30,}$/.test(value)) return true;
  // Stripe keys
  if (/^sk_(?:live|test)_[A-Za-z0-9]{20,}$/.test(value)) return true;
  // Anthropic API keys
  if (/^sk-ant-[A-Za-z0-9_-]{20,}$/.test(value)) return true;
  return false;
}

/**
 * Validate Clerk API Key format
 * Clerk secret keys start with "sk_live_" or "sk_test_" for production/test keys
 * Clerk publishable keys start with "pk_live_" or "pk_test_"
 */
export function isValidClerkKey(key) {
  if (!key || !key.startsWith("sk_") || !key.startsWith("pk_")) {
    return false;
  }

  // Clerk keys are base62 encoded after prefix
  const base62Pattern = /^[0-9A-Za-z]+$/;
  if (!base62Pattern.test(key.substring(3))) { // Skip "sk_" or "pk_"
    return false;
  }

  // Minimum length check (Clert keys are typically 36+ chars)
  return key.length >= 36;
}

/**
 * Validate OpenAI API Key format
 * OpenAI keys typically start with "sk-" followed by alphanumeric characters
 */
export function isValidOpenAIKey(key) {
  if (!key || !key.startsWith("sk-")) {
    return false;
  }

  // OpenAI keys use base64url encoding
  const base64urlPattern = /^[A-Za-z0-9_-]+$/;
  if (!base64urlPattern.test(key.substring(3))) { // Skip "sk-"
    return false;
  }

  // OpenAI API keys are typically 51 characters (sk- + 48 chars)
  return key.length === 51;
}

/**
 * Validate AWS Region format
 */
export function isValidAWSRegion(region) {
  if (!region) return false;

  // AWS regions follow pattern: {location}-{number}
  // Examples: us-east-1, eu-west-1, ap-southeast-2
  const awsRegionPattern = /^[a-z]{2}-[a-z]+-\d+$/;
  return awsRegionPattern.test(region);
}

/**
 * Validate DynamoDB table name format
 * Table names must be 3-255 characters, alphanumeric and hyphens only
 */
export function isValidDynamoTableName(name) {
  if (!name || name.length < 3 || name.length > 255) {
    return false;
  }

  const tableNamePattern = /^[a-zA-Z0-9._-]+$/;
  return tableNamePattern.test(name);
}

/**
 * Security check: Detect potential hardcoded secrets in configuration
 */
export function detectPotentialHardcodedSecrets(env) {
  const sensitivePatterns = [
    { pattern: /AKIA[0-9A-Z]{16}/g, name: "AWS Access Key ID" },
    { pattern: /sk_live_[A-Za-z0-9]{24,}/g, name: "Stripe Live Key" },
    { pattern: /sk_test_[A-Za-z0-9]{24,}/g, name: "Stripe Test Key" },
    { pattern: /ghp_[A-Za-z0-9]{36,}/g, name: "GitHub Personal Access Token" },
    { pattern: /^sk-ant-[A-Za-z0-9_-]{20,}$/g, name: "Anthropic API Key" },
  ];

  const detected = [];

  for (const [key, value] of Object.entries(env || process.env)) {
    for (const { pattern, name } of sensitivePatterns) {
      if (pattern.test(value)) {
        detected.push({
          variable: key,
          secretType: name,
          matches: value.match(pattern)?.length || 0
        });
      }
    }
  }

  return detected;
}

/**
 * Main validation function
 */
export function validateCredentials() {
  console.log("=== Credential Validation Report ===\n");

  // Get environment variables
  const env = process.env;

  // 1. Check for sensitive variables
  const sensitiveVars = Object.entries(env)
    .filter(([name, value]) => isSensitiveEnvVar(name, value))
    .map(([name, value]) => ({
      name,
      redactedValue: value.length > 8 ? `${value.slice(0, 4)}...${value.slice(-4)}` : "****"
    }));

  console.log("Sensitive environment variables detected:");
  sensitiveVars.forEach(v => console.log(`  - ${v.name}: ${v.redactedValue}`));

  // 2. Validate known credential formats
  console.log("\nCredential Format Validation:");

  if (env.CLERK_SECRET_KEY) {
    console.log(`  Clerk Secret Key: ${isValidClerkKey(env.CLERK_SECRET_KEY) ? "✓ VALID" : "✗ INVALID"}`);
  }

  if (env.OPENAI_API_KEY) {
    console.log(`  OpenAI API Key: ${isValidOpenAIKey(env.OPENAI_API_KEY) ? "✓ VALID" : "✗ INVALID"}`);
  }

  if (env.AWS_REGION) {
    console.log(`  AWS Region: ${isValidAWSRegion(env.AWS_REGION) ? "✓ VALID" : "✗ INVALID"}`);
  }

  if (env.DYNAMO_TABLE_NAME) {
    console.log(`  DynamoDB Table Name: ${isValidDynamoTableName(env.DYNAMO_TABLE_NAME) ? "✓ VALID" : "✗ INVALID"}`);
  }

  // 3. Security audit
  console.log("\nSecurity Audit:");
  const hardcodedSecrets = detectPotentialHardcodedSecrets(env);
  if (hardcodedSecrets.length > 0) {
    console.log("  ⚠️  Potential hardcoded secrets detected:");
    hardcodedSecrets.forEach(s => console.log(`     - ${s.secretType} in ${s.variable} (${s.matches} match(es))`));
  } else {
    console.log("  ✓ No hardcoded secrets detected in environment variables");
  }

  console.log("\n=== End of Report ===");
}

// Export for use as module
export default {
  isSensitiveEnvVar,
  isValidClerkKey,
  isValidOpenAIKey,
  isValidAWSRegion,
  isValidDynamoTableName,
  detectPotentialHardcodedSecrets,
  validateCredentials
};

// Run validation if executed directly
if (import.meta.url === `file://${process.argv[1]}`) {
  validateCredentials();
}

#!/usr/bin/env node
/**
 * Secure Credential Redaction Utility
 * 
 * Usage: node extract-redacted-credentials.mjs
 * 
 * Generates a redacted preview of all credential environment variables
 * for rotation tracking. Safe to run in production - never outputs full secrets.
 * 
 * Output format: VARIABLE_NAME=XXXX...XXXX (first 4 + last 4 chars)
 */

import process from 'process';

// Credential variables that should be tracked for rotation
const CREDENTIAL_NAMES = [
  // Clerk authentication
  'CLERK_SECRET_KEY',
  'CLERK_PUBLISHABLE_KEY',
  'CLERK_JWT_PUBLIC_KEY',
  'CLERK_JWT_PUBLIC_KEY_RAW',

  // AI/ML providers
  'OPENAI_API_KEY',
  'ANTHROPIC_API_KEY',

  // AWS credentials
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'AWS_SESSION_TOKEN',
  'AWS_DEFAULT_PROFILE',
  'AWS_PROFILE',

  // Database/Storage
  'DATABASE_URL',
  'REDIS_URL',
  'DYNAMO_DB_URL',

  // Monitoring/Logging
  'LOGFIRE_TOKEN',
  'SENTRY_DSN',
  'DATADOG_API_KEY',
  'NEW_RELIC_LICENSE_KEY',

  // External services
  'STRIPE_SECRET_KEY',
  'GITHUB_TOKEN',
  'SLACK_WEBHOOK_URL',

  // Application-specific
  'DREDD_HOOK_URL',
  'DREDD_DASHBOARD_ORIGIN',
  'DREDD_AUTH_SECRET',

  // JWT/Token secrets
  'JWT_SECRET',
  'SESSION_SECRET',
  'API_SECRET_KEY',
  'ENCRYPTION_KEY',
];

/**
 * Redact a credential value for safe logging
 * Shows first 4 and last 4 characters, masking the middle
 * 
 * @param {string} value - The credential value to redact
 * @returns {string} - Redacted string in format: "XXXX...XXXX"
 */
function redactCredential(value) {
  if (!value || value.length === 0) {
    return 'NOT_SET';
  }

  if (value.length <= 8) {
    // For very short values, show all but mask with X
    return value.split('').map(() => 'X').join('');
  }

  const first4 = value.slice(0, 4);
  const last4 = value.slice(-4);
  return `${first4}...${last4}`;
}

/**
 * Check if a credential value appears to be a test/canary value
 * @param {string} value - The credential value
 * @returns {boolean} - True if this appears to be a test value
 */
function isTestValue(value) {
  if (!value) return false;
  const lower = value.toLowerCase();
  const canaryIndicators = [
    'canary',
    'test',
    'dummy',
    'placeholder',
    'example',
    'fake',
    'invalid',
    'bad',
    'changeme',
    'todo',
    'fixme',
  ];
  return canaryIndicators.some(indicator => lower.includes(indicator));
}

/**
 * Format a credential entry for output
 * @param {string} name - Environment variable name
 * @param {string} value - Environment variable value
 * @returns {object} - Formatted entry
 */
function formatCredentialEntry(name, value) {
  const redacted = redactCredential(value);
  const isTest = isTestValue(value);
  const isSecret = process.env.SENSITIVE_ENV_DEBUG === '1' || !isTest;

  return {
    name,
    redacted,
    isTest,
    isSecret,
  };
}

/**
 * Get all credentials with their redacted values
 * @returns {Array} - Array of credential entries
 */
function getAllCredentials() {
  const entries = [];

  // Process known credential variables first
  for (const name of CREDENTIAL_NAMES) {
    const value = process.env[name];
    if (value !== undefined) {
      entries.push(formatCredentialEntry(name, value));
    }
  }

  // Then scan all environment variables for sensitive names
  for (const [name, value] of Object.entries(process.env)) {
    // Skip if we already processed it
    if (CREDENTIAL_NAMES.includes(name)) continue;

    // Check if variable name suggests it's a credential
    if (name.includes('KEY') || 
        name.includes('SECRET') || 
        name.includes('TOKEN') || 
        name.includes('PASSWORD') || 
        name.includes('CREDENTIAL') ||
        name.includes('API_KEY')) {
      entries.push(formatCredentialEntry(name, value));
    }
  }

  // Sort alphabetically for consistent output
  entries.sort((a, b) => a.name.localeCompare(b.name));

  return entries;
}

/**
 * Generate markdown table for the credentials report
 */
function generateMarkdownTable(credentials) {
  let markdown = '## Credential Inventory (Redacted)\n\n';
  markdown += '| Variable Name | Redacted Preview | Type |\n';
  markdown += '|---------------|------------------|------|\n';

  for (const cred of credentials) {
    const type = cred.isTest ? 'Test' : 'Production';
    const statusIcon = cred.isTest ? '⚠️' : '🔒';
    const redacted = cred.redacted.replace(/_/g, '\\_'); // Escape underscores for markdown

    markdown += `| ${cred.name} | ${statusIcon} ${redacted} | ${type} |\n`;
  }

  return markdown;
}

/**
 * Generate CSV output for the credentials report
 */
function generateCSV(credentials) {
  let csv = 'Variable Name,Redacted Preview,Is Test Value,Contains Canary\n';

  for (const cred of credentials) {
    const isCanary = isTestValue(process.env[cred.name]);
    const redacted = cred.redacted.replace(/"/g, '""'); // Escape quotes for CSV
    const value = process.env[cred.name] || '';

    csv += `"${cred.name}","${redacted}",${cred.isTest},${isCanary}\n`;
  }

  return csv;
}

/**
 * Main execution
 */
function main() {
  console.log('='.repeat(60));
  console.log('SECURE CREDENTIAL REDACTION UTILITY');
  console.log('='.repeat(60));
  console.log();
  console.log(`Generated: ${new Date().toISOString()}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log();

  const credentials = getAllCredentials();

  console.log('Found', credentials.length, 'credential(s)');
  console.log();

  // Generate markdown report
  const markdown = generateMarkdownTable(credentials);
  console.log('## Markdown Report (for rotation tracking spreadsheet)');
  console.log();
  console.log(markdown);

  // Generate CSV (for Excel import)
  const csv = generateCSV(credentials);
  console.log('## CSV (copy to clipboard for Excel)');
  console.log();
  console.log(csv);

  // Security summary
  console.log('## Security Summary');
  console.log();
  const productionCount = credentials.filter(c => !c.isTest).length;
  const testCount = credentials.filter(c => c.isTest).length;
  console.log(`Production Credentials: ${productionCount}`);
  console.log(`Test/Credential Values: ${testCount}`);

  if (productionCount > 0) {
    console.log();
    console.log('✅ Production credentials detected - ensure they are managed by AWS Secrets Manager/SSM');
  } else if (testCount > 0) {
    console.log();
    console.log('⚠️  Only test credentials detected - ready for production deployment');
  } else {
    console.log();
    console.log('ℹ️  No credentials detected - verify environment configuration');
  }

  console.log();
  console.log('='.repeat(60));
  console.log('END OF REPORT');
  console.log('='.repeat(60));
}

// Run if executed directly
if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

