  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData),
    'User-Agent': 'Security-Rotation-Logger/1.0'
  }
};

const req = http.request(options, (res) => {
  let data = '';

  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    console.log('Response status:', res.statusCode);
    console.log('Response headers:', JSON.stringify(res.headers, null, 2));
    console.log('Response body:', data);

    if (res.statusCode === 200 || res.statusCode === 201) {
      console.log('✅ Rotation log successfully sent to compliance webhook');
    } else {
      console.log('⚠️  Webhook returned non-success status:', res.statusCode);
    }
  });
});

req.on('error', (error) => {
  console.error('❌ Error sending rotation log:', error.message);
  process.exit(1);
});

req.write(postData);
req.end();
